import { test, expect } from '@playwright/test';

test.describe('Optimistic UI Updates for Liking Posts', () => {
  let baseURL: string;

  test.beforeEach(async ({ page }) => {
    baseURL = process.env.BASE_URL || 'http://localhost:3000';
    await page.goto(`${baseURL}/posts`);

    // Wait for posts to load
    await page.waitForLoadState('networkidle');
  });

  test('should show optimistic like count increase immediately when liking a post', async ({ page }) => {
    // Find the first post
    const firstPost = page.locator('[data-testid="post-item"]').first();

    // Get initial like count
    const likeButton = firstPost.getByRole('button', { name: /like/i });
    const likeCountBefore = await firstPost.getByTestId('like-count').textContent();
    const initialCount = parseInt(likeCountBefore || '0', 10);

    // Intercept the API call to delay the response
    await page.route('**/api/posts/*/like', async (route) => {
      // Delay the response to simulate network latency
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Click like button
    await likeButton.click();

    // Verify optimistic update - count should increase immediately
    const likeCountAfter = await firstPost.getByTestId('like-count').textContent();
    const optimisticCount = parseInt(likeCountAfter || '0', 10);

    expect(optimisticCount).toBe(initialCount + 1);

    // Verify button state changes immediately
    expect(await likeButton).toHaveAttribute('aria-pressed', 'true');

    // Wait for API response to complete
    await page.waitForLoadState('networkidle');

    // Verify final count matches after API response
    const likeCountFinal = await firstPost.getByTestId('like-count').textContent();
    const finalCount = parseInt(likeCountFinal || '0', 10);
    expect(finalCount).toBe(initialCount + 1);
  });

